 matrix=pd.DataFrame(rows);factorf=pd.DataFrame(factor);auditf=pd.DataFrame(audits);mp=root/OUT/"read_write_causal_matrix_v28.parquet";fp=root/OUT/"channel_write_factorial_v28.parquet";ap=root/OUT/"strict_write_fidelity_v28.parquet";matrix.to_parquet(mp,index=False,compression="zstd");factorf.to_parquet(fp,index=False,compression="zstd");auditf.to_parquet(ap,index=False,compression="zstd")
