 formal={"V28_A":A,"V28_B":B,"V28_C":C,"V28_D":False,"V28_E":False,"V28_F":False,"V28_G":False,"V28_H":False};names=["V28-A_PRESENT_FUTURE_STATE_DISSOCIATION_CONFIRMED","V28-B_NATURAL_STATE_WRITE_CAUSALLY_NECESSARY","V28-C_FULL_OUTGOING_STATE_TRANSPLANTABLE"] if A and B and C else [f"V28-{k}_{'TRUE' if v else 'FALSE'}" for k,v in formal.items()]
 x={**formal,"formal_outcomes":names,"primary_outcome":"+".join(names),"development_primary_gate":dev["gates"]["REC+Conv"],"validation_primary_gate":val["gates"]["REC+Conv"],"final_confirmation":fin,"full_transplant_development":td["profiles"]["REC+Conv+KV_last_slot_previous_copy"],"full_transplant_validation":tv["profiles"]["REC+Conv+KV_last_slot_previous_copy"],"partial_transplant_REC_Conv_development":td["profiles"]["REC+Conv"],"partial_transplant_REC_Conv_validation":tv["profiles"]["REC+Conv"],"factorial_interaction_over_joint_median":{"development":float(factorf[factorf.role=="development"].interaction_over_joint.median()),"validation":float(factorf[factorf.role=="validation"].interaction_over_joint.median())},"strict_writeback_rows":len(auditf),"strict_writeback_all_pass":bool(auditf.writeback_exact.all()),"current_all_preserved":bool(auditf.current_preserved.all()),"tokens_all_identical":bool(auditf.token_identical.all()),"full_transplant_is_complete_cache_identity_control":True,"single_channel_transplant_not_confirmed":True,"REC_Conv_partial_transplant_not_confirmed":True,"KV_old_state_restore_not_valid":True,"natural_write_predictiveness_not_causally_adjudicated":True,"H2_REMAINS":True,"H3_AUTHORIZED":False,"DYNAMIC_STATE_SEARCH_AUTHORIZED":False,"AUTONOMOUS_CONTROLLER_AUTHORIZED":False,"historical_final_opened":False,"v28_independent_final_opened":True,"wording":"causal separation of already-computed current readout from natural outgoing persistent-state commit; no compact-state claim"};x["ADJUDICATION_HASH"]=hashlib.sha256(json.dumps(x,sort_keys=True,separators=(",",":")).encode()).hexdigest();jp=root/OUT/"v28_adjudication.json";write_json_atomic(jp,x);fr=stage_freeze(root,"adjudication",[SOURCE,str(jp.relative_to(root)),str(mp.relative_to(root)),str(fp.relative_to(root)),str(ap.relative_to(root)),"artifacts/token_state_transaction_v28_final_response.freeze.json","artifacts/token_state_transaction_v28_transplant_validation_analysis.freeze.json","artifacts/token_state_transaction_v28_horizons_validation.freeze.json","artifacts/token_state_transaction_v28_wrong_write_validation.freeze.json"],{"formal_outcomes":names,"ADJUDICATION_HASH":x["ADJUDICATION_HASH"],"strict_writeback_all_pass":x["strict_writeback_all_pass"],"historical_final_opened":False,"v28_independent_final_opened":True,"H3_AUTHORIZED":False});return {"freeze_digest":fr["freeze_digest"],"formal_outcomes":names,"final_median_h1_q":fin["median_h1_q"],"writeback_rows":len(auditf),"factorial_interaction_over_joint_median":x["factorial_interaction_over_joint_median"]}
